// ===========================
// Error Handling Tests (4 tests)
// ===========================

describe("SnapchatWebhookProcessor - Error Handling", () => {
  let processor: SnapchatWebhookProcessor;

  beforeAll(() => {
    processor = new SnapchatWebhookProcessor();
  });

  it("should throw error for missing eventType", async () => {
    const payload = {
      creativeId: "creative-no-event",
      adAccountId: "adaccount-err",
    };

    await expect(processor.parse(payload as unknown as Record<string, unknown>)).rejects.toThrow(
      "Invalid Snapchat webhook: missing eventType or creativeId"
    );
  });

  it("should throw error for missing creativeId", async () => {
    const payload = {
      eventType: "CREATIVE_APPROVED",
      adAccountId: "adaccount-err2",
    };

    await expect(processor.parse(payload as unknown as Record<string, unknown>)).rejects.toThrow(
      "Invalid Snapchat webhook: missing eventType or creativeId"
    );
  });

  it("should throw error for completely empty payload", async () => {
    const payload = {};

    await expect(processor.parse(payload as unknown as Record<string, unknown>)).rejects.toThrow(
      "Invalid Snapchat webhook: missing eventType or creativeId"
    );
  });

  it("should default to POST_UPDATED for unknown event type", async () => {
    const payload = {
      eventType: "UNKNOWN_EVENT_TYPE",
      creativeId: "creative-unknown",
      adAccountId: "adaccount-unknown",
      reviewStatus: "UNKNOWN",
      timestamp: "2024-06-15T19:00:00Z",
      internalEventId: "evt-unknown",
    };

    const result = await processor.parse(payload as unknown as Record<string, unknown>);

    assert.strictEqual(result.eventType, "POST_UPDATED");
  });
});

