describe("SnapchatWebhookProcessor - Process", () => {
  let processor: SnapchatWebhookProcessor;

  beforeAll(() => {
    processor = new SnapchatWebhookProcessor();
  });

  it("should process CREATIVE_APPROVED without throwing", async () => {
    const normalizedData = { eventType: "CREATIVE_APPROVED", creativeId: "c-1" };
    const relatedEntities = { postId: "post-1", channelId: "ch-1" };

    await expect(processor.process(normalizedData, relatedEntities)).resolves.not.toThrow();
  });

  it("should process CREATIVE_REJECTED without throwing", async () => {
    const normalizedData = {
      eventType: "CREATIVE_REJECTED",
      creativeId: "c-2",
      reviewStatusReasons: ["bad content"],
    };
    const relatedEntities = { postId: "post-2", channelId: "ch-2" };

    await expect(processor.process(normalizedData, relatedEntities)).resolves.not.toThrow();
  });

  it("should process CREATIVE_PROCESSING without throwing", async () => {
    const normalizedData = { eventType: "CREATIVE_PROCESSING", creativeId: "c-3" };
    const relatedEntities = { postId: "post-3", channelId: "ch-3" };

    await expect(processor.process(normalizedData, relatedEntities)).resolves.not.toThrow();
  });
});

